const classificationCounts = DHQ_CLASSIFICATION_COUNTS

const classificationBaseNodes = [
  { id: "all", label: `${classificationCounts.total} published items`, stage: 0, type: "source" },
  { id: "single", label: "One source tag", stage: 1, type: "tag-state" },
  { id: "multiple", label: "Multiple source tags", stage: 1, type: "tag-state" },
  { id: "absent", label: "No source tag", stage: 1, type: "missing" },
  { id: "single-display", label: "One displayed tag", stage: 2, type: "display" },
  { id: "unclassified", label: "Unclassified", stage: 2, type: "missing" }
]

const classificationBaseEdges = [
  { source: "all", target: "single", value: classificationCounts.single, kind: "source metadata" },
  { source: "all", target: "multiple", value: classificationCounts.multiple, kind: "source metadata" },
  { source: "all", target: "absent", value: classificationCounts.absent, kind: "source metadata" },
  { source: "single", target: "single-display", value: classificationCounts.single, kind: "direct" },
  { source: "absent", target: "unclassified", value: classificationCounts.absent, kind: "metadata absent" }
]

export function buildClassificationFlow(mode = "default") {
  const canonicalMode = mode === "default" ? "default" : ["preserve", "uncertainty", "uncertainty-preserving"].includes(mode) ? "preserve" : null
  if (!canonicalMode) throw new RangeError(`Unknown classification mode "${mode}".`)
  const preserve = canonicalMode === "preserve"
  const nodes = preserve
    ? [...classificationBaseNodes, { id: "multiple-retained", label: "Multiple tags retained", stage: 2, type: "preserved" }]
    : classificationBaseNodes
  const edges = [
    ...classificationBaseEdges,
    preserve
      ? { source: "multiple", target: "multiple-retained", value: classificationCounts.multiple, kind: "preserved" }
      : { source: "multiple", target: "single-display", value: classificationCounts.multiple, kind: "forced-display" }
  ]
  return {
    nodes: nodes.map(node => ({ ...node })),
    edges: edges.map(edge => ({ ...edge })),
    summary: {
      mode: canonicalMode,
      total: classificationCounts.total,
      single: classificationCounts.single,
      multiple: classificationCounts.multiple,
      absent: classificationCounts.absent,
      finding: preserve
        ? `${classificationCounts.multiple} published items retain their multiple source tags.`
        : `${classificationCounts.multiple} published items are reduced to one displayed tag.`
    }
  }
}
